from __future__ import annotations

import api as _api

app = _api.app

_original_yipman_html = _api.yipman_html

_PATCH = r'''
<style id="promo-v476-css">
@media (min-width:760px){
#ydesk .promo476{display:grid;gap:10px}.promo476 .modebar{display:flex;gap:7px;flex-wrap:wrap}.promo476 .modebtn{border:1px solid #d8e3ed;background:#fff;border-radius:9px;padding:8px 11px;font-size:11px;font-weight:900;color:#36516b}.promo476 .modebtn.active{background:#0b72f4;border-color:#0b72f4;color:#fff}.promo476 .panel{border:1px solid #dfe7ef;border-radius:11px;padding:11px;background:#fbfdff}.promo476 .grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px}.promo476 label{display:block;font-size:8px;font-weight:900;color:#6d8094;text-transform:uppercase}.promo476 input,.promo476 select,.promo476 textarea{width:100%;margin-top:4px;border:1px solid #d7e2ec;border-radius:8px;background:#fff;padding:8px;font-size:11px;outline:0}.promo476 textarea{min-height:145px;resize:vertical;font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.promo476 .searchres{margin-top:6px;border:1px solid #dfe7ef;border-radius:9px;overflow:hidden;background:#fff;max-height:220px;overflow-y:auto}.promo476 .srow{padding:8px 9px;border-bottom:1px solid #edf2f6;cursor:pointer}.promo476 .srow:hover{background:#eef6ff}.promo476 .srow b{font-size:11px}.promo476 .srow div{font-size:9px;color:#6f8091;margin-top:2px}.promo476 .items{display:grid;gap:6px}.promo476 .item{display:grid;grid-template-columns:minmax(180px,1fr) 100px 38px;gap:7px;align-items:center;border:1px solid #dfe7ef;border-radius:9px;padding:8px;background:#fff}.promo476 .item b{font-size:11px}.promo476 .item small{display:block;color:#728294;font-size:9px}.promo476 .remove{border:1px solid #ffc9d1;background:#fff1f3;color:#b42f44;border-radius:8px;height:34px;font-weight:1000}.promo476 .actions476{display:flex;gap:7px;flex-wrap:wrap}.promo476 .primary476{border:0;background:#0b72f4;color:#fff;border-radius:8px;padding:9px 12px;font-size:10px;font-weight:1000}.promo476 .ghost476{border:1px solid #d8e3ed;background:#fff;color:#405a73;border-radius:8px;padding:9px 12px;font-size:10px;font-weight:900}.promo476 .review{margin-top:8px;border:1px solid #dfe7ef;border-radius:9px;background:#fff;padding:8px}.promo476 .warn{background:#fff4df;border:1px solid #f1d69f;color:#815a00;border-radius:8px;padding:8px;font-size:9px}.promo476 .ok{background:#edf9f2;border:1px solid #caead6;color:#226d47;border-radius:8px;padding:8px;font-size:9px}.promo476 .savedrow{display:flex;gap:7px;align-items:end}.promo476 .savedrow>div{flex:1}
}
</style>
<script id="promo-v476-js">
(()=>{
 if(!window.matchMedia('(min-width:760px)').matches)return;
 const $=(s,r=document)=>r.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const state={mode:'saved',items:[],recognized:[],lists:[]};
 const api=async(url,opt={})=>{const c=new AbortController(),t=setTimeout(()=>c.abort(),30000);try{const r=await fetch(url,{...opt,signal:c.signal});const txt=await r.text();let d={};try{d=txt?JSON.parse(txt):{}}catch{d={detail:txt}}if(!r.ok)throw new Error(d.detail||('HTTP '+r.status));return d}finally{clearTimeout(t)}};
 const iso=v=>{if(!v)return'';const m=String(v).trim().match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})$/);if(!m)return v;let y=+m[3];if(y<100)y+=2000;return y+'-'+String(+m[1]).padStart(2,'0')+'-'+String(+m[2]).padStart(2,'0')};
 function delivery(){return $('#ydDel')?.value||''} function nextDelivery(){return $('#ydNext')?.value||''}
 function currentSetup(){return {name:$('#p476name')?.value.trim()||('Manual Promotion '+($('#p476start')?.value||new Date().toISOString().slice(0,10))),start:$('#p476start')?.value||'',end:$('#p476end')?.value||'',delivery:$('#p476del')?.value||delivery(),next:$('#p476next')?.value||nextDelivery()}}
 function normalize(r){const upc=String(r.upc||r.selling_upc||r.code||r.upc_code||r.item_upc||'').trim();const desc=r.description||r.item_name||r.name||r.family_article_name||r.english_name||r.family_name||upc;return {upc,description:desc,raw:r}}
 function itemHtml(x,i){return '<div class="item"><div><b>'+esc(x.description||x.upc)+'</b><small>'+esc(x.upc||'Needs match')+'</small></div><input class="p476price" data-i="'+i+'" type="number" step="0.01" min="0" placeholder="Sale $" value="'+esc(x.price??'')+'"><button class="remove" data-rm="'+i+'">×</button></div>'}
 function renderItems(){const box=$('#p476items');if(!box)return;box.innerHTML=state.items.length?state.items.map(itemHtml).join(''):'<div class="warn">No promotion items added yet.</div>';box.querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{state.items.splice(+b.dataset.rm,1);renderItems()});box.querySelectorAll('.p476price').forEach(inp=>inp.oninput=()=>state.items[+inp.dataset.i].price=inp.value)}
 async function search(q){q=q.trim();if(!q)return[];const d=await api('/v1/yipman/promotion-item-search?q='+encodeURIComponent(q)+'&limit=20');return (d.rows||d.items||d.results||[]).map(normalize).filter(x=>x.upc)}
 async function doSearch(){const inp=$('#p476search'),out=$('#p476searchres'),q=inp.value.trim();if(!q){out.innerHTML='';return}out.innerHTML='<div class="srow">Searching…</div>';try{const a=await search(q);out.innerHTML=a.length?a.map((x,i)=>'<div class="srow" data-pick="'+i+'"><b>'+esc(x.description)+'</b><div>'+esc(x.upc)+'</div></div>').join(''):'<div class="srow">No match</div>';out.querySelectorAll('[data-pick]').forEach(el=>el.onclick=()=>{const x=a[+el.dataset.pick];if(!state.items.some(z=>z.upc===x.upc))state.items.push({...x,price:''});inp.value='';out.innerHTML='';renderItems()})}catch(e){out.innerHTML='<div class="srow">'+esc(e.message)+'</div>'}}
 function datesIn(s){return [...String(s).matchAll(/\b\d{1,2}[\/-]\d{1,2}[\/-]\d{2,4}\b/g)].map(m=>iso(m[0]))}
 function parsePaste(txt){const lines=String(txt).split(/\r?\n/).map(s=>s.trim()).filter(Boolean),allDates=datesIn(txt);let start='',end='',del='',nxt='';const candidates=[];for(const line of lines){const ds=datesIn(line),low=line.toLowerCase();if(low.includes('next')&&low.includes('deliver')&&ds[0]){nxt=ds[0];continue}if(low.includes('deliver')&&ds[0]){del=ds[0];continue}if((low.includes('promo')||low.includes('promotion')||low.includes('sale'))&&ds.length>=2){start=ds[0];end=ds[1];continue}const pm=line.match(/\$\s*(\d+(?:\.\d{1,2})?)/);const nums=[...line.matchAll(/\b\d{8,14}\b/g)].map(m=>m[0]);if(pm||nums.length){let q=nums[0]||line.replace(/\$\s*\d+(?:\.\d{1,2})?/g,' ').replace(/\b\d{1,2}[\/-]\d{1,2}[\/-]\d{2,4}\b/g,' ').replace(/\s+/g,' ').trim();if(q)candidates.push({query:q,price:pm?pm[1]:'',line})}}
 if(!start&&allDates.length>=2){start=allDates[0];end=allDates[1]}return {start,end,del,nxt,candidates}}
 async function recognizePaste(){const txt=$('#p476paste').value.trim(),msg=$('#p476review');if(!txt){msg.innerHTML='<div class="warn">Paste the promotion form first.</div>';return}const p=parsePaste(txt);if(p.start)$('#p476start').value=p.start;if(p.end)$('#p476end').value=p.end;if(p.del)$('#p476del').value=p.del;if(p.nxt)$('#p476next').value=p.nxt;msg.innerHTML='<div class="warn">Recognizing '+p.candidates.length+' item row(s)…</div>';const found=[];for(const c of p.candidates){try{const a=await search(c.query);if(a.length===1)found.push({...a[0],price:c.price,sourceLine:c.line,match:'Exact/Best'});else if(a.length>1)found.push({...a[0],price:c.price,sourceLine:c.line,match:'Best of '+a.length});else found.push({upc:'',description:c.query,price:c.price,sourceLine:c.line,match:'Needs review'})}catch{found.push({upc:'',description:c.query,price:c.price,sourceLine:c.line,match:'Needs review'})}}
 state.recognized=found;state.items=found.filter(x=>x.upc);renderItems();msg.innerHTML='<div class="'+(found.some(x=>!x.upc)?'warn':'ok')+'"><b>Recognition review</b><br>'+found.map(x=>esc(x.description)+' · '+esc(x.upc||'NEEDS MATCH')+' · $'+esc(x.price||'—')+' · '+esc(x.match)).join('<br>')+'</div>'}
 async function savePromotion(){const s=currentSetup();document.querySelectorAll('.p476price').forEach(inp=>state.items[+inp.dataset.i].price=inp.value);if(!s.start||!s.end||!s.delivery||!s.next)return alert('Enter promotion start/end and delivery/next delivery dates.');if(!state.items.length)return alert('Add at least one promotion item.');if(state.items.some(x=>!(Number(x.price)>0)))return alert('Enter a valid promotion price for every item.');const body={list_name:s.name,source_filename:state.mode==='paste'?'PASTED_PROMOTION_FORM':'MANUAL_SEARCH_ENTRY',items:state.items.map(x=>({upc:x.upc,description:x.description,promotion_type:'CUSTOM',promotion_start_date:s.start,promotion_end_date:s.end,promotion_price:Number(x.price)}))};const btn=$('#p476save');btn.disabled=true;btn.textContent='SAVING…';try{const d=await api('/v1/yipman/promotion-lists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});await loadLists(d.list_id||d.id);$('#ydDel').value=s.delivery;$('#ydNext').value=s.next;await calcSelected();state.items=[];renderItems();btn.textContent='SAVED'}catch(e){alert(e.message);btn.textContent='SAVE & CALCULATE'}finally{btn.disabled=false}}
 async function loadLists(selectId){const d=await api('/v1/yipman/promotion-lists?limit=40');state.lists=d.rows||d.lists||[];const sel=$('#p476saved');if(!sel)return;sel.innerHTML='<option value="">Choose saved promotion…</option>'+state.lists.map(x=>'<option value="'+esc(x.list_id||x.id)+'">'+esc(x.list_name||x.name||('List #'+(x.list_id||x.id)))+'</option>').join('');if(selectId)sel.value=String(selectId)}
 async function calcSelected(){const id=Number($('#p476saved')?.value||0);if(!id)return;const out=$('#p476out');out.innerHTML='<div class="warn">Calculating promotion order…</div>';try{const d=await api('/v1/yipman/promotion-ordering/calculate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({list_id:id,delivery_date:$('#ydDel')?.value||delivery(),next_delivery_date:$('#ydNext')?.value||nextDelivery(),temporary_oh_overrides:{}})});const a=d.rows||d.items||[];out.innerHTML='<div class="review"><b>'+a.length+' promotion family/item result(s)</b><br>'+a.slice(0,30).map(x=>esc(x.family_name||x.item_name||x.upc||'Item')+' · suggested '+esc(x.suggested_qty??x.suggested_order_qty??0)+' '+esc(x.uom||x.order_uom||'')).join('<br>')+'</div>'}catch(e){out.innerHTML='<div class="warn">'+esc(e.message)+'</div>'}}
 function panel(){return '<div class="card"><div class="cardhead"><h3>Promotion Ordering</h3><span class="badge purple">MANUAL + PASTE + SAVED</span></div><div class="cardbody promo476"><div class="modebar"><button class="modebtn active" data-mode="saved">Saved Promotions</button><button class="modebtn" data-mode="manual">+ Add Items Manually</button><button class="modebtn" data-mode="paste">📋 Paste Promotion Form</button></div><div class="panel"><div class="grid2"><label>Promotion Name<input id="p476name" placeholder="Manual Promotion"></label><label>Promotion Start<input id="p476start" type="date"></label><label>Promotion End<input id="p476end" type="date"></label><label>Delivery Date<input id="p476del" type="date" value="'+esc(delivery())+'"></label><label>Next Delivery Date<input id="p476next" type="date" value="'+esc(nextDelivery())+'"></label></div></div><div id="p476savedPanel" class="panel"><div class="savedrow"><div><label>Saved Promotion<select id="p476saved"></select></label></div><button class="primary476" id="p476calc">CALCULATE</button></div></div><div id="p476manualPanel" class="panel" style="display:none"><label>Search UPC / Article / Family / Item<input id="p476search" autocomplete="off" placeholder="Type to search"></label><div id="p476searchres" class="searchres"></div><div style="margin-top:8px"><b style="font-size:10px">Promotion Items</b><div id="p476items" class="items" style="margin-top:6px"></div></div></div><div id="p476pastePanel" class="panel" style="display:none"><label>Paste Promotion Form<textarea id="p476paste" placeholder="Paste Excel rows, email text, or promotion form here…"></textarea></label><div class="actions476" style="margin-top:7px"><button class="ghost476" id="p476recognize">RECOGNIZE PROMOTION</button></div><div id="p476review"></div></div><div class="actions476"><button class="primary476" id="p476save" style="display:none">SAVE & CALCULATE</button></div><div id="p476out"></div></div></div>'}
 function bind(){document.querySelectorAll('.modebtn').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;document.querySelectorAll('.modebtn').forEach(x=>x.classList.toggle('active',x===b));$('#p476savedPanel').style.display=state.mode==='saved'?'block':'none';$('#p476manualPanel').style.display=state.mode==='manual'?'block':'none';$('#p476pastePanel').style.display=state.mode==='paste'?'block':'none';$('#p476save').style.display=state.mode==='saved'?'none':'inline-block'});$('#p476calc').onclick=calcSelected;$('#p476save').onclick=savePromotion;$('#p476recognize').onclick=recognizePaste;let tm;$('#p476search').oninput=()=>{clearTimeout(tm);tm=setTimeout(doSearch,220)};renderItems();loadLists().catch(e=>$('#p476out').innerHTML='<div class="warn">'+esc(e.message)+'</div>')}
 function patch(){const root=$('#ydOrderMain');if(!root||root.dataset.promo476==='1')return;const h=root.textContent||'';if(!h.includes('Promotion Ordering'))return;root.dataset.promo476='1';root.innerHTML=panel();bind()}
 new MutationObserver(()=>{const r=$('#ydOrderMain');if(r&&r.dataset.promo476==='1'&&!(r.textContent||'').includes('MANUAL + PASTE + SAVED'))r.dataset.promo476='';patch()}).observe(document.documentElement,{subtree:true,childList:true});setInterval(patch,700);
})();
</script>
'''


def _patched_yipman_html(version: str = "") -> str:
    html = _original_yipman_html(version)
    return html.replace("</body>", _PATCH + "</body>", 1)

_api.yipman_html = _patched_yipman_html
